package com.scriptles.cabinet.profile.controller;
import com.scriptles.cabinet.profile.dto.*; import com.scriptles.cabinet.profile.service.PostService; import com.scriptles.cabinet.security.AuthenticatedUser; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/v1/profiles/{profileId}/posts") @RequiredArgsConstructor public class PostController { private final PostService posts; @PostMapping public PostResponse create(@AuthenticationPrincipal AuthenticatedUser viewer,@PathVariable UUID profileId,@Valid @RequestBody PostRequest request){return posts.create(viewer.id(),profileId,request);} }
